#!/usr/bin/env python3
"""Read ids.txt and print the next order id."""

import sys
from pathlib import Path

DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def base36_encode(n: int, width: int) -> str:
    """Encode integer n as a base-36 string padded to width."""
    chars = []
    for _ in range(width):
        chars.append(DIGITS[n % 36])
        n //= 36
    return "".join(reversed(chars))


def base36_decode(s: str) -> int:
    """Decode a base-36 string to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + DIGITS.index(ch.upper())
    return n


def main() -> None:
    ids_file = Path("ids.txt")
    if not ids_file.exists():
        print("ORD-0000")
        return

    last_id = None
    with ids_file.open() as f:
        for line in f:
            line = line.strip()
            if line:
                last_id = line

    if last_id is None:
        print("ORD-0000")
        return

    suffix = last_id.split("-", 1)[1]
    num = base36_decode(suffix)
    num += 1
    next_suffix = base36_encode(num, len(suffix))
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

