"""Read events.jsonl, remove duplicate events sharing an event_id, write deduped.jsonl."""

import json


def main() -> None:
    seen: set[str] = set()
    with open("events.jsonl", encoding="utf-8") as inf, \
         open("deduped.jsonl", "w", encoding="utf-8") as outf:
        for line in inf:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event.get("event_id")
            if eid not in seen:
                seen.add(eid)
                outf.write(json.dumps(event, ensure_ascii=False) + "\n")


if __name__ == "__main__":
    main()

