"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_hex(path: Path) -> str:
    """Return the SHA-256 hex digest of the file at *path*."""
    h = hashlib.sha256()
    with path.open("rb") as f:
        while True:
            block = f.read(65536)
            if not block:
                break
            h.update(block)
    return h.hexdigest()


def main() -> None:
    if not RELEASE_DIR.is_dir():
        raise SystemExit(f"error: {RELEASE_DIR} does not exist")

    manifest = {}

    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            # Use forward-slash relative path, e.g. "release/app/main.py"
            rel = path.relative_to(Path(".")).as_posix()
            manifest[rel] = sha256_hex(path)

    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2) + "\n")
    print(f"wrote {MANIFEST_PATH} ({len(manifest)} entries)")


if __name__ == "__main__":
    main()

