import os
import re


def report_key(filename: str) -> tuple:
    """Extract numeric part from report-<N>.txt for sorting."""
    match = re.search(r'report-(\d+)', filename)
    return (int(match.group(1)),) if match else (0,)


def main() -> None:
    try:
        entries = os.listdir('reports')
    except FileNotFoundError:
        return

    reports = [e for e in entries if e.startswith('report-') and e.endswith('.txt')]
    reports.sort(key=report_key)

    for r in reports:
        print(r)


if __name__ == '__main__':
    main()

