#!/usr/bin/env python3
"""List report files under reports/ in report order."""

import os
import re


def report_sort_key(filename: str) -> tuple[int, ...]:
    """Return a sort key that orders report-N.txt files by N numerically."""
    m = re.match(r"report-(\d+)\.txt", filename)
    if m:
        return (0, int(m.group(1)))
    # Non-report files come after, in string order.
    return (1, filename)


def main() -> None:
    reports_dir = "reports"
    if not os.path.isdir(reports_dir):
        return

    files = [f for f in os.listdir(reports_dir) if os.path.isfile(os.path.join(reports_dir, f))]
    files.sort(key=report_sort_key)

    for f in files:
        print(f)


if __name__ == "__main__":
    main()

