"""Rotate old entries from app.log to archive.log.

Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every line of app.log starts
with a timestamp formatted YYYY-MM-DD HH:MM:SS followed by a message. Move
every entry whose timestamp is strictly older than 7 days before AS_OF to
archive.log (appending, preserving order), and rewrite app.log with the
remaining entries in their original order.
"""

import sys
from datetime import datetime, timezone


def parse_timestamp(line: str) -> datetime | None:
    """Try to parse the leading 'YYYY-MM-DD HH:MM:SS' from a log line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    cutoff = as_of - 7 * 24 * 3600  # 7 days in seconds
    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff_dt = datetime.fromtimestamp(cutoff, tz=timezone.utc)

    with open("app.log") as f:
        lines = f.readlines()

    # Strip trailing newlines for consistent handling
    lines = [line.rstrip("\n") for line in lines]

    old_lines: list[str] = []  # strictly older than cutoff → archive
    kept_lines: list[str] = []  # at or after cutoff → stay

    for line in lines:
        if not line.strip():
            # Preserve empty lines in their current location
            kept_lines.append(line)
            continue
        ts = parse_timestamp(line)
        if ts is None:
            # If we can't parse the timestamp, keep it in app.log
            kept_lines.append(line)
        elif ts.timestamp() < cutoff:
            old_lines.append(line)
        else:
            kept_lines.append(line)

    # Append old lines to archive.log
    if old_lines:
        with open("archive.log", "a") as f:
            for line in old_lines:
                f.write(line + "\n")

    # Rewrite app.log with kept lines
    with open("app.log", "w") as f:
        for i, line in enumerate(kept_lines):
            if i < len(kept_lines) - 1:
                f.write(line + "\n")
            else:
                f.write(line)
                if not line.endswith("\n"):
                    f.write("\n")


if __name__ == "__main__":
    main()

