#!/usr/bin/env python3
"""Move app.log entries older than 7 days before AS_OF to archive.log."""

import sys
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str) -> datetime | None:
    """Try to parse a YYYY-MM-DD HH:MM:SS prefix from a line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    cutoff = datetime.fromtimestamp(as_of, tz=timezone.utc) - timedelta(days=7)

    with open("app.log", "r") as f:
        lines = f.readlines()

    # Preserve trailing empty lines in app.log by remembering the original line count
    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        ts = parse_timestamp(line)
        if ts is not None and ts < cutoff:
            archive.append(line)
        else:
            keep.append(line)

    if archive:
        with open("archive.log", "a") as f:
            f.writelines(archive)

    with open("app.log", "w") as f:
        f.writelines(keep)


if __name__ == "__main__":
    main()

