import sys
import datetime


def parse_timestamp(line: str) -> datetime.datetime | None:
    """Extract the timestamp from the start of a log line.

    Returns a timezone-aware datetime, or None if the line doesn't start
    with a valid timestamp.
    """
    if len(line) < 19:
        return None
    try:
        return datetime.datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=datetime.timezone.utc
        )
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = datetime.datetime.fromtimestamp(
            int(sys.argv[1]), tz=datetime.timezone.utc
        )
    except (ValueError, OSError):
        print(f"Error: AS_OF must be a valid Unix timestamp in integer seconds",
              file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - datetime.timedelta(days=7)

    # Read all lines from app.log
    try:
        with open("app.log") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found", file=sys.stderr)
        sys.exit(1)

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        line = line.rstrip("\n")
        if not line:
            continue
        ts = parse_timestamp(line)
        if ts is None:
            # Lines without a valid timestamp are kept in app.log
            keep.append(line)
        elif ts < cutoff:
            archive.append(line)
        else:
            keep.append(line)

    # Append archived entries to archive.log
    if archive:
        with open("archive.log", "a") as f:
            for entry in archive:
                f.write(entry + "\n")

    # Rewrite app.log with remaining entries
    with open("app.log", "w") as f:
        for entry in keep:
            f.write(entry + "\n")


if __name__ == "__main__":
    main()

